#[path="../adapter/src/replay_interpolation.rs"]mod interpolation;
fn main(){let path=std::env::args().nth(1).expect("usage: check_pose_replay path.erplay.bones");let data=std::fs::read(path).unwrap();let stride=u32::from_le_bytes(data[16..20].try_into().unwrap())as usize;let count=u64::from_le_bytes(data[24..32].try_into().unwrap())as usize;assert_eq!(&data[..8],b"ERBONES1");assert_eq!(stride,14520);assert_eq!(data.len(),32+count*stride);
 let mut out=[0u8;7200];let begin=std::time::Instant::now();let mut evaluated=0;
 for i in 0..count-1{for offset in [120,7320]{let start=32+i*stride+offset;let a=&data[start..start+7200];let b=&data[start+stride..start+stride+7200];for alpha in [0.,0.1,0.5,0.9,1.]{interpolation::pose_into(a,b,alpha,&mut out).expect("invalid captured pose");if alpha==0.{assert_eq!(&out[..],a);}else if alpha==1.{assert_eq!(&out[..],b);}for bone in out.chunks_exact(48){let q:Vec<f32>=bone[16..32].chunks_exact(4).map(|x|f32::from_le_bytes(x.try_into().unwrap())).collect();let n=q.iter().map(|x|x*x).sum::<f32>();assert!((n-1.).abs()<1e-4);}evaluated+=1;}}}
 println!("REAL FIXTURE PASS: {count} frames, {evaluated} pose evaluations, all 150 quaternion norms/endpoints checked; elapsed {:?}; offline only",begin.elapsed());}
